#if UNITY_EDITOR
using UnityEngine;
using UnityEditor.Media;
using Unity.Collections;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System.Collections;
using System.IO;
using System.Linq;
using System.Reflection;
public class LatestUpdatesRecorder:MonoBehaviour {
 const string Dir="/Users/georgeambrose/Desktop/The Sickness Latest Updates Walkthrough";
 MediaEncoder encoder;RenderTexture rt;Texture2D frame;WoodlandPlayer p;WoodlandMedicalSequence flow;int frames;bool recording;string chapter="";float foot;public string status;float audioPeak;int audioFrames;
 public static string Begin(){var p=Object.FindFirstObjectByType<WoodlandPlayer>();p.inventory.persist=false;var go=new GameObject("Guided showcase recorder");go.transform.SetParent(p.transform);go.AddComponent<LatestUpdatesRecorder>();return "recording starting";}
 IEnumerator Start(){p=GetComponentInParent<WoodlandPlayer>();flow=Object.FindFirstObjectByType<WoodlandMedicalSequence>();Application.runInBackground=true;Time.captureDeltaTime=1f/24;Cursor.lockState=CursorLockMode.Locked;foreach(var h in Object.FindObjectsByType<WoodlandHostile>(FindObjectsSortMode.None))h.enabled=false;p.inventory.persist=false;p.anatomy.ResetForCheckpoint();p.TeleportTo(new Vector3(WoodlandCompanion.PathX(40),WoodlandCompanion.Ground(WoodlandCompanion.PathX(40),40)+.15f,40),0);p.whiteHeadlight=true;p.ApplyTorchMode();p.torch.enabled=true;Directory.CreateDirectory(Dir);File.WriteAllText(Dir+"/Chapters.txt","Guided in-engine Unity demo showcase. Automated camera and route, actual runtime equipment, damage and scene flow. Not a manual input regression or performance benchmark.\n");
 yield return null;
 encoder=new MediaEncoder(Dir+"/The Sickness - Latest Updates with Sound.mp4",new VideoTrackAttributes{width=1280,height=720,frameRate=new MediaRational(24),includeAlpha=false,bitRateMode=UnityEditor.VideoBitrateMode.High},new AudioTrackAttributes{sampleRate=new MediaRational(AudioSettings.outputSampleRate),channelCount=2,language="en"});rt=new RenderTexture(1280,720,0);frame=new Texture2D(1280,720,TextureFormat.RGBA32,false);AudioRenderer.Start();recording=true;StartCoroutine(Capture());yield return Tour();yield return new WaitForSeconds(3);Finish();}
 IEnumerator Capture(){while(recording){yield return new WaitForEndOfFrame();if(!recording)break;var shot=ScreenCapture.CaptureScreenshotAsTexture();Graphics.Blit(shot,rt);var old=RenderTexture.active;RenderTexture.active=rt;frame.ReadPixels(new Rect(0,0,1280,720),0,0);frame.Apply();RenderTexture.active=old;Destroy(shot);if(!encoder.AddFrame(frame))throw new System.Exception("Video frame rejected");int count=AudioRenderer.GetSampleCountForCaptureFrame();if(count>0){using(var data=new NativeArray<float>(count*2,Allocator.Temp)){if(AudioRenderer.Render(data)){for(int n=0;n<data.Length;n++)audioPeak=Mathf.Max(audioPeak,Mathf.Abs(data[n]));encoder.AddSamples(data);audioFrames+=count;}}}frames++;if(frames%120==0)File.WriteAllText(Dir+"/Recording status.txt",chapter+"\nVideo seconds: "+(frames/24f)+"\nAudio peak: "+audioPeak);}}
 void Mark(string s){chapter=s;status=s;File.AppendAllText(Dir+"/Chapters.txt",System.TimeSpan.FromSeconds(frames/24f).ToString(@"mm\:ss")+"  "+s+"\n");}
 void Keys(params Key[] keys){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(keys));}
 void Face(Vector3 target){var d=target-p.eye.transform.position;float yaw=Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg;float pitch=-Mathf.Atan2(d.y,new Vector2(d.x,d.z).magnitude)*Mathf.Rad2Deg;Set("yaw",yaw);Set("pitch",pitch);Set("headYaw",0f);p.transform.rotation=Quaternion.Euler(0,yaw,0);p.eye.transform.localRotation=Quaternion.Euler(pitch,0,0);}
 void Set(string f,object v){typeof(WoodlandPlayer).GetField(f,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(p,v);}
 IEnumerator Look(Vector3 target,float seconds){var start=p.eye.transform.forward;for(float t=0;t<seconds;t+=Time.deltaTime){Face(p.eye.transform.position+Vector3.Slerp(start,(target-p.eye.transform.position).normalized,Mathf.SmoothStep(0,1,t/seconds))*5);yield return null;}}
 float fade;
 void OnGUI(){if(fade>0){GUI.depth=-500;GUI.color=new Color(0,0,0,fade);GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),Texture2D.whiteTexture);GUI.color=Color.white;}}
 IEnumerator Reposition(Vector3 target){for(float t=0;t<.35f;t+=Time.deltaTime){fade=t/.35f;yield return null;}fade=1;p.TeleportTo(new Vector3(target.x,flow.inside?.08f:WoodlandCompanion.Ground(target.x,target.z)+.1f,target.z),p.transform.eulerAngles.y);yield return Wait(.15f);for(float t=0;t<.35f;t+=Time.deltaTime){fade=1-t/.35f;yield return null;}fade=0;}
 IEnumerator Walk(Vector3 target,float speed=1.45f){var cc=p.GetComponent<CharacterController>();float limit=0,stuck=0;while(Vector2.Distance(new Vector2(p.transform.position.x,p.transform.position.z),new Vector2(target.x,target.z))>.2f&&limit<25){limit+=Time.deltaTime;var d=target-p.transform.position;d.y=0;Face(p.eye.transform.position+d.normalized*6);var before=p.transform.position;cc.Move((d.normalized*speed+Vector3.down*4)*Time.deltaTime);stuck=Vector2.Distance(new Vector2(before.x,before.z),new Vector2(p.transform.position.x,p.transform.position.z))<.005f?stuck+Time.deltaTime:0;foot+=speed*Time.deltaTime;if(foot>1.35f){foot=0;p.PlayFootstep();}if(stuck>1.2f){File.AppendAllText(Dir+"/Chapters.txt",System.TimeSpan.FromSeconds(frames/24f).ToString(@"mm\:ss")+"  Guided camera cut around route obstruction at "+target+"\n");yield return Reposition(target);break;}yield return null;}}
 IEnumerator Trail(float z){while(p.transform.position.z<z-.25f){float next=Mathf.Min(z,p.transform.position.z+2);yield return Walk(new Vector3(WoodlandCompanion.PathX(next),0,next));}}
 IEnumerator Wait(float s){yield return new WaitForSeconds(s);}
 IEnumerator Tour(){
 Mark("Updated woodland approach and research building");yield return Wait(2);yield return Trail(44);yield return Look(flow.entrance.position+Vector3.up*2,2);yield return Wait(2);yield return Walk(flow.generator.position+Vector3.back*1.8f);yield return Look(flow.generator.position+Vector3.up*.7f,1);
 Mark("Generator wire repair: drag matching wires, then power switch");yield return flow.StartGenerator();yield return Wait(2);for(int wire=0;wire<3;wire++){var source=GameObject.Find("Loose wire "+wire).GetComponent<RectTransform>();var terminal=GameObject.Find("Terminal "+wire).GetComponent<RectTransform>();Vector2 a=RectTransformUtility.WorldToScreenPoint(null,source.position),b=RectTransformUtility.WorldToScreenPoint(null,terminal.position);flow.repair.BeginDrag(wire);for(float time=0;time<1.6f;time+=Time.deltaTime){var position=Vector2.Lerp(a,b,Mathf.SmoothStep(0,1,time/1.6f));InputSystem.QueueStateEvent(Mouse.current,new MouseState{position=position});yield return null;}flow.repair.EndDrag(b);yield return Wait(.8f);}yield return Wait(1.5f);flow.repair.SwitchOn();yield return Wait(3);Mark("Powered generator and hospital entry");yield return Walk(flow.entrance.position+Vector3.back*1.7f);yield return flow.Enter();foreach(var h in flow.interior.hostiles)h.enabled=false;p.anatomy.ResetForCheckpoint();yield return Wait(2);
 Mark("Reception detail, glow sticks and flickering fixtures");p.inventory.Add("glowstick",3);WoodlandGlowstick.Drop(p);yield return Look(p.transform.position+Vector3.forward*2,1);yield return Wait(2);yield return Walk(new Vector3(200,0,5));yield return Wait(1);yield return Walk(new Vector3(200,0,10));yield return Wait(6);
 Mark("Clinical room and corridor dressing");yield return Walk(new Vector3(198.2f,0,11));yield return Walk(new Vector3(195.3f,0,11));yield return Look(new Vector3(194.8f,1.2f,15),2);yield return Wait(2);yield return Look(new Vector3(193,1.2f,10),2);yield return Wait(2);yield return Walk(new Vector3(200,0,11));yield return Walk(new Vector3(200,0,18));yield return Wait(1);yield return Walk(new Vector3(200,0,21));
 Mark("Aiming lean left and right");var enemy=flow.interior.hostiles[0];yield return Look(enemy.transform.position+Vector3.up,1);Keys(Key.Q,Key.Z);yield return Wait(2);Keys(Key.Q,Key.X);yield return Wait(2);Keys(Key.Q);yield return Wait(1);
 Mark("Bright hallway muzzle flashes, hostile voice and injury response");enemy.enabled=true;for(int n=0;n<3;n++){p.anatomy.ResetForCheckpoint();Face(enemy.transform.position+Vector3.up*.95f);p.Fire();yield return Wait(.9f);}Keys();for(int n=0;n<6;n++){p.anatomy.ResetForCheckpoint();Face(enemy.transform.position+Vector3.up*.8f);yield return Wait(1);}enemy.enabled=false;p.anatomy.ResetForCheckpoint();p.TryReload();yield return Wait(4);foreach(var h in flow.interior.hostiles)h.enabled=false;
 Mark("Downed exile crawls through blood before the breach");yield return Walk(new Vector3(200.8f,0,25));yield return Walk(new Vector3(200.5f,0,28));var crawl=Object.FindFirstObjectByType<MedicalCrawlingExile>();yield return Look(crawl.transform.position+Vector3.back*.7f,1.5f);WoodlandGlowstick.Drop(p);for(float watch=0;watch<7;watch+=Time.deltaTime){Face(crawl.transform.position+Vector3.back*.7f);yield return null;}p.anatomy.ResetForCheckpoint();
 Mark("Crowbar door animation");yield return Walk(new Vector3(200.65f,0,31));yield return Walk(new Vector3(200,0,32.4f));yield return Look(flow.interior.jammedDoor.position+Vector3.right*1.18f+Vector3.up,1);flow.interior.Use();yield return Wait(5.2f);
 Mark("Thornback appears behind; low battery, blood and stagger");yield return Walk(new Vector3(200,0,36));yield return Look(flow.interior.thornback.position+Vector3.up*1.3f,1.5f);Keys(Key.Q);yield return Wait(1);for(int n=0;n<4;n++){p.anatomy.ResetForCheckpoint();Face(flow.interior.thornback.position+Vector3.up*1.3f);p.Fire();yield return Wait(.9f);}Keys();float wait=0;while(!flow.interior.finished&&wait<48){wait+=Time.deltaTime;Face(flow.interior.thornback.position+Vector3.up*1.3f);yield return null;}Mark("THE SICKNESS");yield return Wait(4);
 }

 void Finish(){if(!recording)return;recording=false;AudioRenderer.Stop();encoder.Dispose();encoder=null;Time.captureDeltaTime=0;Keys();File.WriteAllText(Dir+"/Recording status.txt","COMPLETE\nDuration "+frames/24f+" seconds\nFrames "+frames+"\nAudio frames "+audioFrames+"\nAudio peak "+audioPeak);status="COMPLETE";}
 void OnDestroy(){Finish();if(rt)Destroy(rt);if(frame)Destroy(frame);}
}

#endif
